// v1.7.17 — owner, 9 Nov 2026 (Sydney time): “auto play quá sơ sài chỉ hiện tại đang bấm nút, phải làm cả workflow, ví dụ viết món,
// chụp ảnh… sau đó lên món cho các bữa, nấu, đi chợ, đi chợ về cất đồ check stock… Cho tôi thêm workflow đi, nhớ là mọi thứ phải
// hoạt động như dự tính.” Pop-ups: all eight workflows proposed, more added, in v1.7.17, and every step runs even after one fails.
//
// Each workflow does a whole job the way the family does it, through the screens, and checks what the job must change in the
// family's data: amounts in the pantry, the shopping list, portions, spending, the menu. They run inside “Tự chạy thử” on a fresh
// sample family (or a fresh copy of the family's data) with nothing saved or sent (see ladybug-autoplay.ts).
(function(){
 const G:any=globalThis;const A=G.bepAutoplay;if(!A?.kit)return;const k=A.kit,{tap,type,waitFor,waitGone,find,expect,go,part,skip,sleep,aT}=k;
 // ── what the checks read ─────────────────────────────────────────────────────────────────────────────────────────────────────
 const ing=(id:string)=>(INGREDIENTS as any)[id];
 const idOf=(...names:string[])=>{for(const n of names){const id=Object.keys(INGREDIENTS).find(x=>String(ing(x)[0]).toLowerCase()===n.toLowerCase());if(id)return id}return ''};
 const tomorrow=()=>addDays(sydneyDate(),1);
 const weekOf=(d:string)=>planWeek(state,planStartOf(state,d));
 const mealOf=(d:string,t:string)=>weekOf(d).days[d]?.[t];
 const need=(id:string,start:string,end:string)=>{const w=weekOf(start);const row=shopping(state,w,start,end).find((r:any)=>r.id===id&&!r.skip);return row?(+row.need||+row.qty||+row.toBuy||0):0};
 const toBuy=(start:string,end:string)=>shopping(state,weekOf(start),start,end).filter((r:any)=>shoppingHasAmount(r)&&!r.skip);
 const stockOf=(id:string)=>typeof stock==='function'?+stock(state,id):state.pantry.filter((p:any)=>p.ingredient===id).reduce((n:number,p:any)=>n+(+p.qty||0),0);
 const mealQty=(d:string,t:string,id:string)=>+(mealIngredients(mealOf(d,t),state)[id]||0);
 // what the whole day's meals need of one ingredient (the shopping list for that day changes by exactly this)
 const dayQty=(d:string,id:string)=>MEAL_TYPES.reduce((n:number,t:string)=>{const m=mealOf(d,t);return n+(m&&!m.cooked?+(mealIngredients(m,state)[id]||0):0)},0);
 const near=(a:number,b:number,tol=0.6)=>Math.abs(a-b)<=Math.max(tol,Math.abs(b)*0.002);
 const setVal=(el:any,v:string)=>{el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};
 async function pick(sel:string,value:string){const e=await waitFor(sel) as HTMLSelectElement;if(k.watch()){e.scrollIntoView({block:'center'});await sleep(300)}setVal(e,value);await sleep(k.watch()?350:60);return e}
 async function submit(id:string){const b=find(`#modal-root [data-action="submit-form"][data-id="${id}"]`)||find(`#${id} button[type="submit"]`);if(b)await tap(b);else (document.getElementById(id) as HTMLFormElement)?.requestSubmit();await sleep(250)}
 // a picture the way a phone camera would hand it over (a drawn plate, not a real photo)
 async function pretendPhoto(input:HTMLInputElement){const c=document.createElement('canvas');c.width=640;c.height=480;const g=c.getContext('2d')!;g.fillStyle='#f4eee2';g.fillRect(0,0,640,480);g.fillStyle='#fff';g.beginPath();g.ellipse(320,250,220,150,0,0,7);g.fill();g.fillStyle='#c87649';g.beginPath();g.ellipse(320,240,140,90,0,0,7);g.fill();g.fillStyle='#5fd36a';for(let i=0;i<9;i++){g.beginPath();g.arc(240+i*20,210+(i%3)*18,9,0,7);g.fill()}
  const blob:Blob=await new Promise(r=>c.toBlob(b=>r(b!),'image/jpeg',.9));const dt=new DataTransfer();dt.items.add(new File([blob],'mon-thu.jpg',{type:'image/jpeg'}));input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}))}
 // write a family dish through “Viết món ăn”
 async function writeDish(name:string,rows:[string,number][],{time=40,prep=15,yieldN=4,steps=['Sơ chế 15 phút.','Nấu 25 phút.'],photo=false}={}){
  await go('recipes');await tap('#main [data-fm="new"]');const form=await waitFor('#family-recipe-form');
  await type('#family-recipe-form [name="name"]',name);await type('#family-recipe-form [name="time"]',String(time));if(prep)await type('#family-recipe-form [name="prepTime"]',String(prep));await type('#family-recipe-form [name="yield"]',String(yieldN));
  const add=()=>find('#family-recipe-form [data-rci="add"]')||find('#family-recipe-form .rc-add-row');
  for(let i=0;i<rows.length;i++){let li=form.querySelectorAll('.rc-ing-row')[i] as HTMLElement|undefined;if(!li){const b=add();if(b)await tap(b);await sleep(120);li=form.querySelectorAll('.rc-ing-row')[i] as HTMLElement|undefined}expect(li,aT('Không thêm được dòng nguyên liệu.','Could not add an ingredient row.'));
   const [id,qty]=rows[i];setVal(li!.querySelector('.rc-ing-name-input'),String(ing(id)[0]));setVal(li!.querySelector('.rc-ing-qty'),String(qty));setVal(li!.querySelector('.rc-ing-unit'),ing(id)[1]);const shop=li!.querySelector('.rc-ing-shop-input') as HTMLInputElement|null;if(shop&&!shop.checked)shop.click();await sleep(k.watch()?250:30)}
  const st=form.querySelector('[name="steps"]') as HTMLTextAreaElement|null;if(st)setVal(st,steps.join('\n'));
  if(photo){const inp=form.querySelector('[data-rc-file="library"]') as HTMLInputElement;expect(inp,aT('Không có chỗ thêm ảnh món.','No dish photo field.'));await pretendPhoto(inp);await waitFor('#family-recipe-form #rc-photo-preview img',6000)}
  await submit('family-recipe-form');await waitGone('#family-recipe-form',6000);
  const r=state.recipes.find((x:any)=>x.name===name);expect(r,aT(`Món “${name}” không được lưu.`,`“${name}” was not saved.`));return r}
 // put a dish on a meal through the meal's “Thêm món ăn”
 async function addToMeal(date:string,meal:string,r:any){weekStart=planStartOf(state,date);await go('planner');weekStart=planStartOf(state,date);render();
  const b=await waitFor(`#main [data-fm="edit-meal"][data-date="${date}"][data-type="${meal}"]`);await tap(b);await waitFor('#family-meal-form');
  await type('#family-meal-form #meal-dish-search',r.name);const box=await waitFor(`#family-meal-form .family-select-row[data-id="${r.id}"] input[name="recipe"]`) as HTMLInputElement;if(!box.checked)await tap(box);
  await submit('family-meal-form');await waitGone('#family-meal-form',5000);expect(mealOf(date,meal).recipes.some((x:any)=>x.id===r.id),aT(`“${r.name}” chưa có trong bữa.`,`“${r.name}” is not on the meal.`))}
 // add stock through Tủ → “Thêm thực phẩm”
 async function addStock(id:string,qty:number,{place='fridge',expiry=''}={}){await go('pantry');await tap('#main [data-action="add-stock"]');await waitFor('#modal-root #stock-form');
  await pick('#modal-root #stock-ing',id);await type('#modal-root #stock-qty',String(qty));await pick('#modal-root #stock-place',place);if(expiry){const e=find('#modal-root #stock-form [name="expiry"]')||find('#modal-root #stock-expiry');if(e)setVal(e,expiry)}
  const before=stockOf(id);await submit('stock-form');await waitGone('#modal-root #stock-form',4000);expect(near(stockOf(id),before+qty),aT(`Tủ không thêm ${qty} ${ing(id)[1]} ${ing(id)[0]}.`,`The pantry did not add ${qty} of ${ing(id)[0]}.`))}
 // “Báo cơm”: everyone eats at home for this meal (on a family's own data nobody may have answered yet)
 async function everyoneHome(date:string,meal:string){selectedDate=date;weekStart=planStartOf(state,date);attendanceType=meal;await go('today');selectedDate=date;attendanceType=meal;render();await sleep(150);
  for(const p of state.members){const sel=find(`#main select[data-change="attendance"][data-id="${p.id}"]`) as HTMLSelectElement|undefined;const saved=mealOf(date,meal)?.attendance?.[p.id];if(sel&&!sel.disabled&&(sel.value!=='home'||saved!=='home'))await pick(`#main select[data-change="attendance"][data-id="${p.id}"]`,'home')/* also when the box shows “home” but nothing was answered yet */}
  const m=mealOf(date,meal);expect(m&&state.members.every((p:any)=>m.attendance?.[p.id]==='home'||!m.attendance),aT('Chưa báo cơm được cho cả nhà.','Could not mark everyone home.'))}
 const W=(id:string,vi:string,en:string,dvi:string,den:string,run:()=>Promise<void>)=>A.register({id,vi,en,dvi,den,run,workflow:true});

 // ── 1. a new dish with a photo → on a meal → on the shopping list with the right amounts ─────────────────────────────────
 W('wf-dish','Workflow: món mới → ảnh → lên bữa → đi chợ','Workflow: new dish → photo → meal → shopping','Viết món có định lượng, thêm ảnh, lưu, xếp vào bữa tối mai, danh sách đi chợ có đủ nguyên liệu đúng lượng.','Write a dish with amounts, add a photo, save, put it on tomorrow’s dinner, the list has every ingredient in the right amount.',async()=>{
  const chicken=idOf('Thịt gà','Gà'),ginger=idOf('Gừng'),fish=idOf('Nước mắm');let r:any;
  await part(aT('Viết món: tên, thời gian, chuẩn bị, nguyên liệu, các bước, ảnh','Write the dish: name, times, ingredients, steps, photo'),async()=>{r=await writeDish('Gà kho gừng (thử)',[[chicken,500],[ginger,30],[fish,30]],{photo:true})});
  await part(aT('Món lưu đúng định lượng và thời gian','The dish keeps its amounts and times'),async()=>{expect(r,aT('Chưa có món.','No dish.'));const q=(id:string)=>r.ingredients.find((i:any)=>i.id===id)?.qty;
   expect(q(chicken)===500&&q(ginger)===30&&q(fish)===30,aT(`Định lượng sai: ${JSON.stringify(r.ingredients)}`,`Wrong amounts: ${JSON.stringify(r.ingredients)}`));expect(r.time===40&&r.prepTime===15,aT(`Thời gian sai: nấu ${r.time}, chuẩn bị ${r.prepTime}.`,`Wrong times: cook ${r.time}, prep ${r.prepTime}.`))});
  await part(aT('Ảnh món được gắn vào món','The photo is on the dish'),async()=>{for(let i=0;i<30&&!r?.photo?.key;i++)await sleep(100);expect(r?.photo?.key,aT('Ảnh không được lưu cùng món.','The photo was not kept.'))});
  await part(aT('Món có trong Kho món ăn','The dish is in Recipes'),async()=>{await go('recipes');const q=find('#main input[type="search"]')||find('#main .recipe-tools input');if(q){await type('#main '+(q.id?'#'+q.id:'input[type="search"]'),'Gà kho gừng')}await sleep(300);expect(/Gà kho gừng \(thử\)/.test((document.getElementById('main') as HTMLElement).innerText),aT('Không thấy món trong Kho món ăn.','Not listed in Recipes.'))});
  const d=tomorrow();await part(aT('Xếp vào bữa tối ngày mai','Put it on tomorrow’s dinner'),async()=>{await addToMeal(d,'dinner',r)});
  await part(aT('Danh sách đi chợ có đủ nguyên liệu, đúng lượng','The shopping list has each ingredient in the right amount'),async()=>{const m=mealOf(d,'dinner'),serv=mealServings(m,state),y=familyYield(r);
   for(const [id,q] of [[chicken,500],[ginger,30],[fish,30]] as [string,number][]){const want=q*serv/y,got=need(id,d,d);expect(got+0.6>=want,aT(`${ing(id)[0]}: cần ${Math.round(want)} ${ing(id)[1]} mà danh sách ghi ${Math.round(got)}.`,`${ing(id)[0]}: needs ${Math.round(want)} but the list says ${Math.round(got)}.`))}
   await go('shopping');const nm=String(typeof shopIngName==='function'?shopIngName(chicken):ing(chicken)[0]);const stillToBuy=toBuy(...(shopDates() as [string,string])).some((x:any)=>x.id===chicken);if(stillToBuy)expect((document.getElementById('main') as HTMLElement).innerText.toLowerCase().includes(nm.toLowerCase().split(' ')[0]),aT('Trang Đi chợ không hiện nguyên liệu của món.','The shopping page does not show it.'))})});

 // ── 2. the week: plan → shop → put away → check the pantry ─────────────────────────────────────────────────────────────────
 W('wf-week','Workflow: lên kế hoạch tuần → đi chợ → cất đồ → kiểm tủ','Workflow: plan the week → shop → put away → check stock','Ai vắng, xem trước, lên thực đơn; đi chợ đánh dấu hết, cất đồ; tủ có đủ đúng lượng, danh sách không còn gì phải mua.','Who is away, preview, plan; shop and tick all, put away; the pantry holds the right amounts and nothing is left to buy.',async()=>{
  let start='',days:string[]=[],awayDay='',who='';
  await part(aT('Mở “Lên kế hoạch tuần”','Open “Plan the week”'),async()=>{await go('today');const b=find('#main [data-flow="plan-start"]');if(b)await tap(b);else{if(typeof weekPlanStart!=='function')throw Error('weekPlanStart');weekPlanStart()}await waitFor('#modal-root [data-flow="plan-away"]');start=(G.weekPlan||{}).start||'';const chips=[...document.querySelectorAll('#modal-root [data-flow="plan-away"]')] as HTMLElement[];days=[...new Set(chips.map(c=>c.dataset.date!))];expect(days.length===7,aT('Không đủ 7 ngày.','Not 7 days.'))});
  await part(aT('Chọn một người vắng một ngày','Mark one person away for a day'),async()=>{const c=document.querySelectorAll('#modal-root [data-flow="plan-away"]')[2] as HTMLElement;who=c.dataset.id!;awayDay=c.dataset.date!;await tap(c,{still:true});expect(c.getAttribute('aria-pressed')==='true'||find(`#modal-root [data-flow="plan-away"][data-id="${who}"][data-date="${awayDay}"][aria-pressed="true"]`),aT('Ngày vắng không được chọn.','The away day was not marked.'))});
  await part(aT('Tiếp → khách → xem trước → lên thực đơn','Next → guests → preview → plan'),async()=>{for(let i=0;i<4&&!find('#modal-root [data-flow="plan-preview"]');i++){const n=find('#modal-root [data-flow="plan-next"]');if(!n)break;await tap(n);await sleep(200)}
   await tap('#modal-root [data-flow="plan-preview"]');const ap=await waitFor('#modal-root [data-fm="apply"]',8000);await tap(ap);await sleep(400);closeModal();const w=weekOf(days[0]);expect(days.every(d=>MEAL_TYPES.some((t:string)=>w.days[d]?.[t]?.recipes?.length)),aT('Có ngày chưa có món.','A day has no dishes.'));
   // away days go to the family calendar (“Ai vắng”, portions deducted), not to each meal's own list
   const total=state.members.reduce((n:number,p:any)=>n+(+p.weight||0),0),wt=+state.members.find((p:any)=>p.id===who).weight||0,dm=w.days[awayDay]?.dinner;
   expect(availabilityEntry(state,who,awayDay,'dinner')?.status==='away',aT('Lịch gia đình không ghi người đó vắng.','The family calendar does not show them away.'));
   expect(!dm?.recipes?.length||near(mealServings(dm,state),total-wt,0.01),aT(`Bữa tối ngày vắng tính ${dm?mealServings(dm,state):'?'} suất, cần ${total-wt}.`,`Dinner that day counts ${dm?mealServings(dm,state):'?'} portions, expected ${total-wt}.`))});
  let bought:Record<string,number>={};
  await part(aT('Đi chợ: bắt đầu, đánh dấu hết','Shop: start and tick everything'),async()=>{weekStart=planStartOf(state,days[0]);await go('shopping');weekStart=planStartOf(state,days[0]);render();const rows=toBuy(...(shopDates() as [string,string]));expect(rows.length>=3,aT('Danh sách đi chợ gần như trống.','The list is nearly empty.'));bought=Object.fromEntries(rows.map((r:any)=>[r.id,+r.need||+r.qty||0]));
   await tap('#main [data-flow="shop-start"]');await waitFor('#main .shop-mode-bar');for(let i=0;i<80;i++){const box=find('#main .shopping-group .shop-row input.check[data-change="bought"]:not(:checked)');if(!box)break;await tap(box)}
   expect(!find('#main .shopping-group .shop-row input.check[data-change="bought"]:not(:checked)'),aT('Còn món chưa đánh dấu được.','Some items could not be ticked.'))});
  await part(aT('“Đi chợ xong” → cất đồ đúng chỗ','“Done shopping” → put away'),async()=>{await tap('#main [data-flow="shop-done"]');await waitFor('#modal-root #store-form');await submit('store-form');await waitGone('#modal-root #store-form',5000)});
  await part(aT('Kiểm tủ: đủ đúng lượng, không còn gì phải mua','Check stock: right amounts, nothing left to buy'),async()=>{const short=Object.entries(bought).filter(([id,q])=>stockOf(id)+0.6<q&&!state.pantry.some((p:any)=>p.ingredient===id&&p.qtyEstimated));
   expect(!short.length,aT(`Tủ thiếu: ${short.map(([id,q])=>`${ing(id)[0]} ${Math.round(stockOf(id))}/${Math.round(q)}`).join(', ')}`,`Pantry short: ${short.map(([id])=>ing(id)[0]).join(', ')}`));const left=toBuy(...(shopDates() as [string,string]));expect(!left.length,aT(`Còn phải mua: ${left.map((r:any)=>ing(r.id)?.[0]||r.id).join(', ')}`,`Still to buy: ${left.length}`));
   await go('pantry');expect(document.querySelectorAll('#main .stock-row, #main .pantry-row, #main [data-action="edit-stock"]').length>=3,aT('Trang Tủ không hiện đồ vừa cất.','The pantry page does not show what was put away.'))})});

 // ── 3. cook tonight: enough in the pantry → cooking mode → cooked → the pantry goes down → undo puts it back ─────────────────
 W('wf-cook','Workflow: nấu bữa tối → trừ tủ → bỏ đánh dấu','Workflow: cook dinner → pantry down → undo','Thêm đồ vào tủ cho bữa tối, nấu từng bước có hẹn giờ, “Đã nấu” trừ đúng lượng, bỏ đánh dấu trả lại tủ.','Stock tonight’s ingredients, cook step by step with a timer, “Cooked” takes the right amounts, undo puts them back.',async()=>{
  const d=sydneyDate();const m=mealOf(d,'dinner');if(!m?.recipes?.length)skip(aT('Tối nay chưa có món.','No dinner dishes tonight.'));const needs:Record<string,number>=mealIngredients(m,state);const ids=Object.keys(needs).filter(id=>needs[id]>0).slice(0,6);
  await part(aT('Cả nhà báo ăn ở nhà','Everyone eats at home'),async()=>{await everyoneHome(d,'dinner');const nn=mealIngredients(mealOf(d,'dinner'),state);for(const id of Object.keys(needs))delete needs[id];Object.assign(needs,nn);ids.splice(0,ids.length,...Object.keys(nn).filter(id=>nn[id]>0).slice(0,6))});
  await part(aT('Thêm đồ cần cho bữa tối vào tủ','Stock tonight’s ingredients'),async()=>{for(const id of ids){if(stockOf(id)+0.6<needs[id])await addStock(id,Math.ceil(needs[id]-stockOf(id)+1))}});
  let before:Record<string,number>={};
  await part(aT('Mở chế độ nấu, bước tiếp, hẹn giờ','Cooking mode, next step, timer'),async()=>{before=Object.fromEntries(ids.map(id=>[id,stockOf(id)]));await go('today');const r=state.recipes.find((x:any)=>x.id===m.recipes[0].id)||m.recipes[0];
   const open=find('#main [data-action="start-cooking"]');if(open)await tap(open);else{cooking={recipe:r,step:0};renderCooking()}await waitFor('#modal-root .cooking-step');
   const nx=find('#modal-root [data-action="cooking-next"]');if(nx&&r.steps?.length>1)await tap(nx);const t=find('#modal-root [data-kx="step-timer"]')||find('#modal-root [data-action="start-timer"]');if(t)await tap(t);closeModal()});
  await part(aT('“Đã nấu” trừ đúng lượng trong tủ','“Cooked” takes the right amounts'),async()=>{await go('today');const b=await waitFor(`#main [data-fm="cook-meal"][data-date="${d}"][data-type="dinner"]`);await tap(b);await sleep(250);
   if(find('#modal-root .cook-ahead-list'))await tap('#modal-root [data-fm="cook-ahead"][data-only]');await sleep(250);expect(mealOf(d,'dinner').cooked,aT('Bữa chưa được đánh dấu đã nấu.','Not marked cooked.'));
   const wrong=ids.filter(id=>!near(before[id]-stockOf(id),Math.min(needs[id],before[id]),1));expect(!wrong.length,aT(`Trừ sai: ${wrong.map(id=>`${ing(id)[0]} trừ ${Math.round(before[id]-stockOf(id))}/${Math.round(needs[id])}`).join(', ')}`,`Wrong amounts taken: ${wrong.join(', ')}`))});
  await part(aT('Bỏ đánh dấu đã nấu → tủ trả lại','Undo → the pantry is back'),async()=>{const b=await waitFor(`#main [data-fm="cook-meal"][data-date="${d}"][data-type="dinner"]`);await tap(b);await sleep(300);expect(!mealOf(d,'dinner').cooked,aT('Không bỏ đánh dấu được.','Could not undo.'));
   const off=ids.filter(id=>!near(stockOf(id),before[id],1));expect(!off.length,aT(`Tủ không trở lại như cũ: ${off.map(id=>ing(id)[0]).join(', ')}`,`Pantry not restored: ${off.join(', ')}`))})});

 // ── 4. back from the shops with a receipt (pretend photo → text) → matched → spending ─────────────────────────────────────
 W('wf-receipt','Workflow: đi chợ về → hoá đơn → chi tiêu','Workflow: receipt after shopping → spending','Đánh dấu vài món đã mua, hoá đơn giả lập (chữ thay ảnh), đọc dòng, ghép đúng món đã mua, lưu; chi tiêu tuần tăng đúng số tiền.','Tick a few items bought, a pretend receipt, read, match to what was bought, save; this week’s spending rises by the total.',async()=>{
  const egg=idOf('Trứng gà','Trứng'),rice=idOf('Gạo'),total=21.4;let n0=0;
  await part(aT('Đánh dấu đã mua trong Đi chợ','Tick items as bought'),async()=>{await go('shopping');for(const id of [egg,rice]){const b=find(`#main .shop-row input.check[data-change="bought"][data-id="${id}"]`);if(b&&!(b as HTMLInputElement).checked)await tap(b)}});
  await part(aT('Hoá đơn giả lập: dán chữ, đọc dòng','Pretend receipt: paste text, read lines'),async()=>{n0=state.receipts.length;await go('expenses');const nb=find('[data-feature="receipt-new"]');if(nb)await tap(nb);else newReceipt();await waitFor('#modal-root #receipt-raw');
   await type('#modal-root #receipt-raw',['WOOLWORTHS','EGGS FREE RANGE 12PK 7.40','RICE JASMINE 5KG 14.00','TOTAL 21.40'].join('\n'));await tap('#modal-root [data-feature="receipt-parse"]');await waitFor('#modal-root .receipt-line');expect(document.querySelectorAll('#modal-root .receipt-line').length>=2,aT('Không đọc được 2 dòng.','Two lines not read.'))});
  await part(aT('Ghép từng dòng với món đã mua','Match each line'),async()=>{for(const [re,id,q] of [[/EGG/i,egg,'trung'],[/RICE/i,rice,'gao']] as [RegExp,string,string][]){const line=[...document.querySelectorAll('#modal-root .receipt-line')].find(l=>re.test((l.querySelector('.receipt-label') as HTMLInputElement)?.value||'')) as HTMLElement;expect(line,aT('Thiếu dòng.','Line missing.'));
    const sel=line.querySelector('select.receipt-match') as HTMLSelectElement;if(sel.value!==id){const i=line.dataset.index;await tap(line.querySelector('.rm-search') as HTMLElement);await type(`#modal-root .receipt-line[data-index="${i}"] .rm-search`,q);const o=await waitFor(`#modal-root .receipt-line[data-index="${i}"] .rm-opt[data-rm-value="${id}"]`);await tap(o)}expect(sel.value===id,aT(`Dòng ${re.source} chưa ghép được.`,`${re.source} not matched.`))}});
  await part(aT('Lưu khoản chi','Save the spending'),async()=>{const t=find('#modal-root #receipt-total') as HTMLInputElement;if(t&&!+t.value)setVal(t,String(total));await tap('#modal-root [data-feature="receipt-save"]');await sleep(400);if(find('#modal-root [data-feature="receipt-save"]'))await tap('#modal-root [data-feature="receipt-save"]');await sleep(400);closeModal();expect(state.receipts.length===n0+1,aT('Hoá đơn chưa được lưu.','Not saved.'))});
  await part(aT('Hoá đơn ghi đúng món và tiền; chi tiêu tuần có số tiền đó','The receipt keeps items and money; the week shows it'),async()=>{const r=state.receipts[state.receipts.length-1];expect(near(+r.total,total,0.01),aT(`Tổng hoá đơn ${r.total}, không phải ${total}.`,`Total ${r.total}, not ${total}.`));
   expect([egg,rice].every(id=>r.items.some((i:any)=>i.ingredient===id)),aT('Dòng hoá đơn không gắn với nguyên liệu.','Lines not linked to ingredients.'));await go('expenses');expect(/21[.,]40/.test((document.getElementById('main') as HTMLElement).innerText),aT('Trang Chi tiêu không có 21,40.','Spending page does not show 21.40.'))})});

 // ── 5. a barcode into the pantry, then used; the second scan is remembered ────────────────────────────────────────────────
 W('wf-barcode','Workflow: mã vạch → tủ → dùng → quét lại','Workflow: barcode → pantry → use → scan again','Quét mã giả lập, ghép Trứng, cất 12 quả; dùng 2 quả; quét lại cùng mã thì app nhớ, không tra lại.','Pretend scan, match Eggs, store 12; use 2; the same code again is remembered, no second lookup.',async()=>{
  const egg=idOf('Trứng gà','Trứng');const code='8934563100011';let s0=0;
  await part(aT('Quét mã (gõ thay camera), ghép Trứng, cất 12 quả','Scan (typed), match Eggs, store 12'),async()=>{s0=stockOf(egg);await go('pantry');await tap('#main [data-kx="scan-open"]');await type('#modal-root #scan-code',code);await tap('#modal-root [data-kx="scan-typed"]');await pick('#modal-root #scan-ing',egg);
   const q=find('#modal-root #scan-qty');if(q)await type('#modal-root #scan-qty','12');await tap('#modal-root [data-kx="scan-save"]');await sleep(300);expect(near(stockOf(egg),s0+12),aT(`Tủ có ${stockOf(egg)} trứng, cần ${s0+12}.`,`Pantry eggs ${stockOf(egg)}, expected ${s0+12}.`))});
  await part(aT('Dùng 2 quả trong Tủ','Use 2 from the pantry'),async()=>{const lot=state.pantry.find((p:any)=>p.ingredient===egg&&p.barcode===code)||state.pantry.find((p:any)=>p.ingredient===egg);expect(lot,aT('Không thấy lô trứng.','No egg lot.'));const before=stockOf(egg);
   await go('pantry');const u=find(`#main [data-action="use-ingredient"][data-id="${lot.id}"]`)||find(`#main [data-action="edit-stock"][data-id="${lot.id}"]`);expect(u,aT('Không có nút dùng / sửa lô trứng.','No use / edit button.'));await tap(u!);await sleep(200);
   const qty=find('#modal-root input[name="qty"], #modal-root #stock-qty, #modal-root input[type="number"]') as HTMLInputElement|undefined;if(qty){setVal(qty,String(u!.dataset.action==='edit-stock'?before-2:2));const f=qty.closest('form') as HTMLFormElement;if(f)await submit(f.id)}
   expect(near(stockOf(egg),before-2),aT(`Sau khi dùng còn ${stockOf(egg)}, cần ${before-2}.`,`After use ${stockOf(egg)}, expected ${before-2}.`))});
  await part(aT('Quét lại cùng mã: app nhớ, không tra lại','Scan again: remembered, no second lookup'),async()=>{const n=(G.__apCalls||[]).filter((x:string)=>x==='barcode').length;await tap('#main [data-kx="scan-open"]');await type('#modal-root #scan-code',code);await tap('#modal-root [data-kx="scan-typed"]');const sel=await waitFor('#modal-root #scan-ing') as HTMLSelectElement;
   expect(sel.value===egg,aT('Lần sau không nhớ ghép Trứng.','Eggs not remembered.'));expect((G.__apCalls||[]).filter((x:string)=>x==='barcode').length===n,aT('Mã đã biết mà vẫn tra lại.','Looked up again.'));closeModal()})});

 // ── 6. guests: portions and shopping follow; invitation, reply, removal ───────────────────────────────────────────────────
 W('wf-guests','Workflow: có khách → suất ăn & đi chợ → lời mời → bỏ khách','Workflow: guests → portions & shopping → invitation → remove','Thêm 2 người lớn cho bữa tối mai: suất ăn và lượng đi chợ tăng theo; gửi lời mời, khách trả lời 3 người; bỏ khách thì quay lại như cũ.','Two adults for tomorrow’s dinner: portions and amounts rise; invite, a reply of 3; removing them puts everything back.',async()=>{
  const d=tomorrow();let s0=0,n0=0,q0=0,idx='';
  await part(aT('Cả nhà báo ăn ở nhà tối mai','Everyone home tomorrow evening'),async()=>{if(!mealOf(d,'dinner')?.recipes?.length)skip(aT('Bữa tối mai chưa có món.','No dinner tomorrow.'));await everyoneHome(d,'dinner')});
  await part(aT('Ghi nhận suất ăn và lượng đi chợ trước','Note portions and amounts'),async()=>{const m=mealOf(d,'dinner');if(!m?.recipes?.length)skip(aT('Bữa tối mai chưa có món.','No dinner tomorrow.'));s0=mealServings(m,state);idx=Object.keys(mealIngredients(m,state))[0];n0=need(idx,d,d);q0=dayQty(d,idx)});
  await part(aT('Thêm nhóm khách 2 người lớn','Add 2 adult guests'),async()=>{selectedDate=d;weekStart=planStartOf(state,d);await go('today');selectedDate=d;render();await sleep(200)/* the shortcut is placed after the page draws */;await tap('#main .guest-shortcut');await waitFor('#modal-root #guest-groups');
   for(const [n,v] of [['from-date',d],['from-type','dinner'],['to-date',d],['to-type','dinner']]){const c=find(`#modal-root [data-guest-pick="${n}"][data-v="${v}"]`);if(c&&c.getAttribute('aria-pressed')!=='true')await tap(c,{still:true})}
   await type('#modal-root [data-guest-name="0"]','Nhà chú Tư (thử)');await tap('#modal-root [data-guest-step="1"][data-k="adults"]',{still:true});
   await tap('#modal-root [data-fm="guests-save"]');await waitGone('#modal-root #guest-groups');expect(near(mealServings(mealOf(d,'dinner'),state),s0+2,0.01),aT(`Suất ăn ${mealServings(mealOf(d,'dinner'),state)}, cần ${s0+2}.`,`Portions ${mealServings(mealOf(d,'dinner'),state)}, expected ${s0+2}.`))});
  await part(aT('Lượng đi chợ tăng đúng phần của bữa tối','Shopping rises by exactly the dinner’s extra share'),async()=>{const n1=need(idx,d,d),want=n0+(dayQty(d,idx)-q0);expect(dayQty(d,idx)>q0&&near(n1,want,1),aT(`${ing(idx)?.[0]}: ${Math.round(n0)} → ${Math.round(n1)}, cần ${Math.round(want)}.`,`${idx}: ${n0} → ${n1}, expected ${want}.`))});
  const openGuests=async()=>{const line=find(`#main [data-fm="guests"][data-date="${d}"][data-type="dinner"]`);if(line)await tap(line);else{await tap('#main .guest-shortcut');await waitFor('#modal-root #guest-groups');for(const [n,v] of [['from-date',d],['from-type','dinner'],['to-date',d],['to-type','dinner']]){const c=find(`#modal-root [data-guest-pick="${n}"][data-v="${v}"]`);if(c&&c.getAttribute('aria-pressed')!=='true')await tap(c)}}};
  await part(aT('Gửi lời mời qua link (máy chủ giả lập)','Send an invitation link (pretend server)'),async()=>{weekStart=planStartOf(state,d);await go('planner');weekStart=planStartOf(state,d);render();await openGuests();await waitFor('#modal-root #guest-groups');const det=find('#modal-root details.guest-invite');if(det)(det as HTMLDetailsElement).open=true;await tap('#modal-root [data-fm="guest-invite"]');await sleep(500);closeModal();
   const g=(mealOf(d,'dinner').guests||[]).find((x:any)=>x.invite);expect(g?.invite?.token==='t3st9k',aT('Lời mời chưa được tạo.','No invitation made.'))});
  await part(aT('Khách trả lời: 3 người sẽ đến','The guests reply: 3 coming'),async()=>{const g=(mealOf(d,'dinner').guests||[]).find((x:any)=>x.invite);G.__apInvites=[{inviteId:g.invite.id,response:{status:'yes',adults:3,kids:0,at:new Date().toISOString()}}];applyInviteReplies(state,G.__apInvites);save();render();
   const g2=(mealOf(d,'dinner').guests||[]).find((x:any)=>x.invite);expect(g2.adults===3&&g2.rsvp?.status==='yes',aT('Câu trả lời chưa vào bữa.','The reply is not on the meal.'));expect(near(mealServings(mealOf(d,'dinner'),state),s0+3,0.01),aT('Suất ăn không theo câu trả lời.','Portions do not follow the reply.'))});
  await part(aT('Bỏ khách → huỷ lời mời, mọi thứ như cũ','Remove → invitation withdrawn, back as before'),async()=>{await go('planner');weekStart=planStartOf(state,d);render();await openGuests();await waitFor('#modal-root #guest-groups');await tap('#modal-root #guest-groups [data-fm="guest-remove"]');await tap('#modal-root [data-fm="guests-save"]');await waitGone('#modal-root #guest-groups');await sleep(300);
   expect(near(mealServings(mealOf(d,'dinner'),state),s0,0.01)&&near(need(idx,d,d),n0,1),aT('Bỏ khách mà suất ăn / đi chợ không trở lại.','Portions / shopping not back.'));expect((G.__apCalls||[]).includes('invite-cancel'),aT('Lời mời chưa được huỷ.','The invitation was not withdrawn.'))})});

 // ── 7. a recipe page → match the unknown lines → save → on a meal → shopping ────────────────────────────────────────────
 W('wf-import','Workflow: nhập món từ link → ghép dòng → lên bữa → đi chợ','Workflow: import a link → match lines → meal → shopping','Trang công thức giả lập; ghép “Bò tái” với Thịt bò và cộng vào đi chợ; lưu; xếp vào bữa trưa mai; danh sách có thịt bò đúng lượng.','A pretend recipe page; match “Bò tái” to Beef and add it to shopping; save; tomorrow’s lunch; the list has the beef.',async()=>{
  const beef=idOf('Thịt bò','Bò');let r:any;
  await part(aT('Nhập món từ link','Import from the link'),async()=>{await go('recipes');await tap('#main [data-kx="import-open"]');await type('#modal-root #kimp-url','https://vi-du.example/pho-bo');await tap('#modal-root [data-kx="import-go"]');await waitFor('#family-recipe-form')});
  await part(aT('Ghép “Bò tái” với Thịt bò, cộng vào đi chợ','Match “Bò tái” to Beef, add to shopping'),async()=>{const li=[...document.querySelectorAll('#family-recipe-form .rc-ing-row')].find(l=>(l.querySelector('.rc-ing-name-input') as HTMLInputElement).value==='Bò tái') as HTMLElement;expect(li,aT('Không có dòng “Bò tái”.','No “Bò tái” line.'));
   setVal(li.querySelector('.rc-ing-name-input'),String(ing(beef)[0]));setVal(li.querySelector('.rc-ing-qty'),'1200');setVal(li.querySelector('.rc-ing-unit'),'g');const sh=li.querySelector('.rc-ing-shop-input') as HTMLInputElement;if(!sh.checked)sh.click();await sleep(100)});
  await part(aT('Lưu món','Save the dish'),async()=>{/* v1.7.19 (B23): an imported page leaves the dish type, protein and servings it does not give for the family */const f=document.querySelector('#family-recipe-form') as any;if(f&&!f.category.value)await pick('#family-recipe-form [name="category"]','noodle');if(f&&!f.protein.value)await pick('#family-recipe-form [name="protein"]','beef');if(f&&!f.yield.value)setVal(f.yield,'4');await submit('family-recipe-form');await waitGone('#family-recipe-form',6000);r=state.recipes.find((x:any)=>x.name==='Phở bò thử');expect(r?.ingredients?.some((i:any)=>i.id===beef&&i.qty===1200),aT(`Món không có 1200 g thịt bò: ${JSON.stringify(r?.ingredients)}`,`No 1200 g beef: ${JSON.stringify(r?.ingredients)}`))});
  const d=tomorrow();await part(aT('Xếp vào bữa trưa mai','Put it on tomorrow’s lunch'),async()=>{const t=mealOf(d,'lunch')?'lunch':'dinner';await addToMeal(d,t,r)});
  await part(aT('Đi chợ có thịt bò đúng lượng','Shopping has the beef'),async()=>{const t=mealOf(d,'lunch')?.recipes?.some((x:any)=>x.id===r.id)?'lunch':'dinner',m=mealOf(d,t),want=1200*mealServings(m,state)/familyYield(r);expect(need(beef,d,d)+0.6>=want,aT(`Thịt bò: cần ${Math.round(want)} g, danh sách ${Math.round(need(beef,d,d))} g.`,`Beef ${need(beef,d,d)} of ${want}.`))})});

 // ── 8. something about to expire → Today suggests using it → a dish with it goes on the meal ────────────────────────────
 W('wf-expiry','Workflow: đồ sắp hết hạn → gợi ý → lên bữa','Workflow: expiring food → suggestion → meal','Thêm đồ hết hạn ngày mai vào tủ; Hôm nay gợi ý dùng; chọn món có đồ đó; món vào bữa.','Add something expiring tomorrow; Today suggests it; pick a dish with it; it goes on the meal.',async()=>{
  const pick0=state.recipes.find((r:any)=>allowedRecipe(r,state)&&r.ingredients?.length&&r.recipeKind!=='dressing');const id=pick0?.ingredients[0]?.id;if(!id)skip('no recipe');
  await part(aT('Thêm đồ hết hạn ngày mai vào tủ','Add something expiring tomorrow'),async()=>{await addStock(id,500,{expiry:tomorrow()});const lot=state.pantry.find((p:any)=>p.ingredient===id&&p.expiry===tomorrow());expect(lot,aT('Hạn dùng không được lưu.','The use-by date was not kept.'))});
  await part(aT('Hôm nay gợi ý dùng đồ đó','Today suggests using it'),async()=>{await go('today');const d=find('#main details:has(.fridge-rescue-card)');if(d)(d as HTMLDetailsElement).open=true;const card=await waitFor('#main .fridge-rescue-card');expect(card.innerText.includes(String(ing(id)[0]))||!!find('#main .fridge-rescue-card [data-fm="use-pantry"]'),aT('Không có gợi ý dùng đồ trong tủ.','No use-it-up suggestion.'))});
  await part(aT('Chọn món có đồ đó → vào bữa','Pick a dish with it → on the meal'),async()=>{await tap('#main .fridge-rescue-card [data-fm="use-pantry"]');const b=await waitFor('#modal-root [data-fm="add-pantry-dish"]');const rid=b.dataset.id!;const r=state.recipes.find((x:any)=>x.id===rid);await tap(b);await sleep(300);
   const m=mealOf(selectedDate,attendanceType);expect(m.recipes.some((x:any)=>x.id===rid),aT('Món gợi ý chưa vào bữa.','The suggested dish is not on the meal.'));expect(r.ingredients.some((i:any)=>state.pantry.some((p:any)=>p.ingredient===i.id)),aT('Món gợi ý không dùng đồ trong tủ.','The dish does not use pantry food.'))})});

 // ── 9. someone away: portions and shopping go down, and back ─────────────────────────────────────────────────────────────
 W('wf-away','Workflow: báo vắng → suất ăn & đi chợ giảm → về nhà','Workflow: away → fewer portions & less to buy → home','Một người báo vắng bữa tối: suất ăn và lượng đi chợ giảm đúng; báo có nhà lại thì như cũ.','Someone is away for dinner: portions and amounts drop; back home restores them.',async()=>{
  const d=sydneyDate();if(!mealOf(d,'dinner')?.recipes?.length||mealOf(d,'dinner').cooked)skip(aT('Tối nay chưa có món.','No dinner tonight.'));const p=state.members[0];let s0=0,id='',n0=0,q0=0;
  await part(aT('Cả nhà báo ăn ở nhà','Everyone eats at home'),async()=>{await everyoneHome(d,'dinner');const m=mealOf(d,'dinner');s0=mealServings(m,state);id=Object.keys(mealIngredients(m,state))[0];n0=need(id,d,d);q0=dayQty(d,id)});
  await part(aT(`${p.name} báo vắng bữa tối`,`${p.name} away for dinner`),async()=>{await go('today');attendanceType='dinner';render();await pick(`#main select[data-change="attendance"][data-id="${p.id}"]`,'away');await sleep(250);
   expect(near(mealServings(mealOf(d,'dinner'),state),s0-p.weight,0.01),aT(`Suất ăn ${mealServings(mealOf(d,'dinner'),state)}, cần ${s0-p.weight}.`,`Portions not reduced.`))});
  await part(aT('Lượng đi chợ giảm đúng phần của người vắng','Shopping drops by exactly their share'),async()=>{const n1=need(id,d,d),want=Math.max(0,n0-(q0-dayQty(d,id)));expect(dayQty(d,id)<q0&&near(n1,want,1),aT(`${ing(id)?.[0]}: ${Math.round(n0)} → ${Math.round(n1)}, cần ${Math.round(want)}.`,`${id}: ${n0} → ${n1}, expected ${want}.`))});
  await part(aT('Báo có nhà lại → như cũ','Back home → as before'),async()=>{await pick(`#main select[data-change="attendance"][data-id="${p.id}"]`,'home');await sleep(250);expect(near(mealServings(mealOf(d,'dinner'),state),s0,0.01)&&near(dayQty(d,id),q0,0.6)&&near(need(id,d,d),n0,1),aT('Không trở lại như cũ.','Not back as before.'))})});

 // ── 10. buy something extra ─────────────────────────────────────────────────────────────────────────────────────────────
 W('wf-extra','Workflow: mua thêm ngoài thực đơn','Workflow: buy something extra','“Mua thêm” Giấy bếp; có trong danh sách; đánh dấu đã mua.','“Buy extra” kitchen paper; on the list; ticked.',async()=>{
  await part(aT('Thêm “Giấy bếp (thử)”','Add “Kitchen paper (test)”'),async()=>{await go('shopping');const b=find('#main [data-action="add-extra"]');expect(b,aT('Không có nút Mua thêm.','No Buy extra button.'));await tap(b!);await waitFor('#modal-root #extra-form');
   await type('#modal-root #extra-name','Giấy bếp (thử)');await type('#modal-root #extra-amount','1');/* v1.7.19: the unit is picked in the shared unit picker, like a person would */if(find('#modal-root #extra-unit-btn')){await tap('#modal-root #extra-unit-btn');await waitFor('#unit-sheet-layer .unit-chip[data-unit-choice="cuộn"]');await tap('#unit-sheet-layer .unit-chip[data-unit-choice="cuộn"]');await tap('#unit-sheet-layer [data-unit-sheet-act="save"]');await sleep(120)}else{const u=find('#modal-root #extra-unit') as HTMLSelectElement;if(u&&!u.value&&u.options?.length)setVal(u,[...u.options].find(o=>o.value)?.value||'')}await submit('extra-form');await sleep(250);
   expect(currentWeek().extras.some((e:any)=>e.name==='Giấy bếp (thử)'),aT('Món mua thêm không được lưu.','Not saved.'))});
  await part(aT('Có trong danh sách, đánh dấu đã mua','On the list, ticked'),async()=>{await go('shopping');const e=currentWeek().extras.find((x:any)=>x.name==='Giấy bếp (thử)');const box=find(`#main [data-change="extra-done"][data-id="${e.id}"]`);expect(box,aT('Không thấy trong danh sách.','Not on the list.'));await tap(box!);await sleep(200);expect(currentWeek().extras.find((x:any)=>x.id===e.id).done,aT('Chưa đánh dấu được.','Not ticked.'))});
  await part(aT('Bỏ đánh dấu → lại cần mua','Untick → to buy again'),async()=>{const e=currentWeek().extras.find((x:any)=>x.name==='Giấy bếp (thử)');await tap(`#main [data-change="extra-done"][data-id="${e.id}"]`);await sleep(200);expect(!currentWeek().extras.find((x:any)=>x.id===e.id).done,aT('Bỏ đánh dấu không được.','Could not untick.'))})});

 // ── 11. change a dish already on the menu → the menu and the list follow ─────────────────────────────────────────────────
 W('wf-edit','Workflow: sửa món đã lên bữa → thực đơn & đi chợ theo','Workflow: change a planned dish → menu & shopping follow','Món gia đình trên bữa tối mai: tăng thịt 400 → 800 g; bữa và danh sách đi chợ đổi theo.','A family dish on tomorrow’s dinner: meat 400 → 800 g; the meal and the list follow.',async()=>{
  const pork=idOf('Thịt heo','Thịt lợn','Thịt ba chỉ');let r:any;const d=tomorrow();
  await part(aT('Viết món và xếp vào bữa tối mai','Write a dish, put it on tomorrow’s dinner'),async()=>{r=await writeDish('Thịt kho (thử)',[[pork,400]],{time:45,prep:10});await addToMeal(d,'dinner',r)});
  let n0=0;await part(aT('Sửa: 400 → 800 g','Edit: 400 → 800 g'),async()=>{n0=need(pork,d,d);await go('recipes');familyRecipeEditor(r.id);const form=await waitFor('#family-recipe-form');const li=[...form.querySelectorAll('.rc-ing-row')].find(l=>(l.querySelector('.rc-ing-qty') as HTMLInputElement).value.startsWith('400')) as HTMLElement;expect(li,aT('Không thấy dòng 400 g.','No 400 g line.'));setVal(li.querySelector('.rc-ing-qty'),'800');await submit('family-recipe-form');await waitGone('#family-recipe-form',5000);
   expect(state.recipes.find((x:any)=>x.id===r.id).ingredients.find((i:any)=>i.id===pork).qty===800,aT('Món chưa đổi thành 800 g.','Not 800 g.'))});
  await part(aT('Bữa và danh sách đi chợ đổi theo','The meal and the list follow'),async()=>{const m=mealOf(d,'dinner'),snap=m.recipes.find((x:any)=>x.id===r.id);expect(snap?.ingredients?.find((i:any)=>i.id===pork)?.qty===800,aT('Món trên bữa vẫn là 400 g.','The meal still has 400 g.'));const n1=need(pork,d,d),add=400*mealServings(m,state)/familyYield(r);expect(near(n1,n0+add,Math.max(1,add*0.02)),aT(`Đi chợ thịt: ${Math.round(n0)} → ${Math.round(n1)}, cần ${Math.round(n0+add)}.`,`${n0} → ${n1}.`))})});

 // ── 12. not liked → kept off the next plan ───────────────────────────────────────────────────────────────────────────────
 W('wf-dislike','Workflow: không thích món → lần lên thực đơn sau tránh','Workflow: disliked → kept off the next plan','Cả nhà bấm “Không thích” một món; lên lại thực đơn tuần thì món đó không còn.','Everyone dislikes a dish; planning the week again leaves it out.',async()=>{
  const d=sydneyDate(),m=mealOf(d,'dinner');const r=m?.recipes?.[0];if(!r)skip(aT('Tối nay chưa có món.','No dinner tonight.'));
  await part(aT(`Cả nhà “Không thích” ${r.name}`,`Everyone dislikes ${r.name}`),async()=>{await go('today');const who=await waitFor(`#main .mr-wrap[data-mr-recipe="${r.id}"] [data-mr="who"]`);await tap(who);await waitFor('#modal-root .mr-panel');
   for(const p of state.members){const b=find(`#modal-root .mr-person[data-mr-member="${p.id}"] [data-mr="dislike"]`);expect(b,aT(`Không có nút “Không thích” cho ${p.name}.`,`No dislike for ${p.name}.`));if(b!.getAttribute('aria-pressed')!=='true')await tap(b!);await sleep(120)}closeModal();
   expect(state.members.every((p:any)=>typeof mrValue!=='function'||mrValue(state,p.id,r.id)==='dislike'),aT('“Không thích” chưa được ghi.','Dislike not recorded.'))});
  await part(aT('Lên lại thực đơn tuần: món đó không còn','Plan the week again: the dish is gone'),async()=>{familyGenerate(state,planStartOf(state,d),{sourceMode:'library'});save();render();const w=weekOf(d);const still=Object.values(w.days).flatMap((day:any)=>MEAL_TYPES.flatMap((t:string)=>day[t]?.cooked||day[t]?.locked?[]:(day[t]?.recipes||[]))).filter((x:any)=>x.id===r.id);
   expect(!still.length,aT(`${r.name} vẫn còn ${still.length} lần trong tuần.`,`${r.name} still planned ${still.length} times.`))});
  await part(aT('Một người đổi ý: bỏ “Không thích”','One person changes their mind'),async()=>{const p=state.members[0],day=Object.entries(weekOf(d).days).find(([,x]:any)=>MEAL_TYPES.some((t:string)=>x[t]?.recipes?.length)) as any;if(typeof mrWhoModal==='function')mrWhoModal(r.id,r.name,day?.[0]||d,'dinner');await waitFor('#modal-root .mr-panel');
   await tap(`#modal-root .mr-person[data-mr-member="${p.id}"] [data-mr="dislike"]`);await sleep(150);closeModal();expect(mrValue(state,p.id,r.id)!=='dislike',aT('Bỏ “Không thích” không được.','Could not undo the dislike.'))})});

 // ── 13. cook once for two meals (leftovers) ──────────────────────────────────────────────────────────────────────────────
 W('wf-ahead','Workflow: nấu một lần cho hai bữa','Workflow: cook once for two meals','Món tối nay cũng có ở bữa trưa mai: “Nấu luôn cho bữa sau”; bữa trưa mai tính là đã nấu, không phải mua hay lấy thêm.','Tonight’s dish is also on tomorrow’s lunch: “cook for the later meal too”; tomorrow counts as cooked ahead, nothing to buy.',async()=>{
  const d=sydneyDate(),t=tomorrow(),m=mealOf(d,'dinner');const r=m?.recipes?.find((x:any)=>!x.batchId);if(!r)skip(aT('Tối nay chưa có món.','No dinner tonight.'));const later=mealOf(t,'lunch')?'lunch':'dinner';
  await part(aT('Cả nhà báo ăn ở nhà tối nay','Everyone home tonight'),async()=>{await everyoneHome(d,'dinner')});
  await part(aT('Đặt cùng món vào bữa sau','The same dish on the later meal'),async()=>{const lm=mealOf(t,later);lm.recipes=[clone(state.recipes.find((x:any)=>x.id===r.id)||r)];for(const p of state.members)lm.attendance[p.id]='home';save();render()});
  await part(aT('Đủ đồ trong tủ cho cả hai bữa','Enough in the pantry for both'),async()=>{const both:Record<string,number>={};for(const mm of [mealOf(d,'dinner'),mealOf(t,later)])for(const [id,q] of Object.entries(mealIngredients(mm,state)))both[id]=(both[id]||0)+(q as number);for(const [id,q] of Object.entries(both))if(stockOf(id)+0.6<q){state.pantry.push({id:'ap-'+id,ingredient:id,qty:Math.ceil(q-stockOf(id)+1),place:'fridge',expiry:''})}save();render()});
  await part(aT('“Đã nấu” → “Nấu luôn cho bữa sau”','“Cooked” → also for the later meal'),async()=>{await go('today');await tap(`#main [data-fm="cook-meal"][data-date="${d}"][data-type="dinner"]`);await waitFor('#modal-root .cook-ahead-list');await tap('#modal-root [data-fm="cook-ahead"]:not([data-only])');await waitGone('#modal-root .cook-ahead-list');
   const lm=mealOf(t,later);expect(mealOf(d,'dinner').cooked&&lm.cooked&&lm.recipes.every((x:any)=>x.cookedAhead),aT('Bữa sau chưa được tính là đã nấu trước.','The later meal is not cooked ahead.'));expect(!Object.keys(mealIngredients(lm,state)).length,aT('Bữa sau vẫn cần nguyên liệu.','The later meal still needs ingredients.'))})});

 // ── 14. lunch boxes: someone takes lunch away ───────────────────────────────────────────────────────────────────────────
 W('wf-pack','Workflow: mang cơm đi','Workflow: a packed lunch','Một người “mang cơm” bữa trưa: vẫn được tính suất, bữa có ghi mang đi; đổi lại ăn ở nhà.','Someone packs lunch: still counted, the meal shows it; back to eating at home.',async()=>{
  const d=sydneyDate(),meal=['lunch','dinner','breakfast'].find(t=>mealOf(d,t)?.recipes?.length&&!mealOf(d,t).cooked)||'';if(!meal)skip(aT('Hôm nay chưa có bữa nào có món.','No meal with dishes today.'));const p=state.members[0];let s0=0;
  await part(aT('Cả nhà báo ăn ở nhà','Everyone eats at home'),async()=>{await everyoneHome(d,meal);s0=mealServings(mealOf(d,meal),state)});
  await part(aT(`${p.name} mang cơm trưa`,`${p.name} packs lunch`),async()=>{await go('today');attendanceType=meal;render();const sel=find(`#main select[data-change="attendance"][data-id="${p.id}"]`) as HTMLSelectElement|undefined;if(!sel||![...sel.options].some(o=>o.value==='packed'))skip(aT('Bữa trưa không có lựa chọn mang cơm.','No packed choice.'));
   await pick(`#main select[data-change="attendance"][data-id="${p.id}"]`,'packed');await sleep(200);expect(mealOf(d,meal).attendance[p.id]==='packed',aT('Chưa ghi mang cơm.','Not packed.'));expect(near(mealServings(mealOf(d,meal),state),s0,0.01),aT('Mang cơm mà bị trừ suất.','A packed lunch was not counted.'))});
  await part(aT('Đổi lại ăn ở nhà','Back to eating at home'),async()=>{await pick(`#main select[data-change="attendance"][data-id="${p.id}"]`,'home');await sleep(200);expect(mealOf(d,meal).attendance[p.id]==='home',aT('Không đổi lại được.','Could not change back.'));attendanceType='dinner'})});
 // ── 15. a new person in the family: “not answered” still counts (the family cooks enough), home keeps it, away removes it ──
 W('wf-member','Workflow: thêm người vào nhà → chưa báo vẫn nấu đủ → báo vắng','Workflow: a new member → counted until they answer → away','Thêm “Bà nội (thử)” 1,2 suất: bữa chưa nấu ghi “chưa báo” và vẫn tính suất để nấu đủ; báo ăn ở nhà giữ nguyên; báo vắng thì suất ăn và lượng đi chợ giảm đúng 1,2 suất.','Add “Grandma (test)” at 1.2 portions: uncooked meals show “not answered” and still count her; eating at home keeps it; away takes 1.2 portions and their amounts off.',async()=>{
  const d=sydneyDate();if(!mealOf(d,'dinner')?.recipes?.length||mealOf(d,'dinner').cooked)skip(aT('Tối nay chưa có món.','No dinner tonight.'));let s0=0,id='',n0=0,q0=0,nm:any=null;
  await part(aT('Cả nhà báo ăn ở nhà tối nay','Everyone home tonight'),async()=>{await everyoneHome(d,'dinner');const m=mealOf(d,'dinner');s0=mealServings(m,state);id=Object.keys(mealIngredients(m,state))[0];n0=need(id,d,d);q0=dayQty(d,id)});
  await part(aT('Cài đặt → Thêm thành viên “Bà nội (thử)”, 1,2 suất','Settings → add “Grandma (test)”, 1.2 portions'),async()=>{const st=document.querySelector('[data-action="settings"]') as HTMLElement|null;expect(st,aT('Không mở được Cài đặt.','Settings not found.'));st!.click();const add=await waitFor('#modal-root [data-action="add-member"]');await tap(add);await waitFor('#modal-root #member-form');
   await type('#modal-root #member-new-name','Bà nội (thử)');await type('#modal-root #member-new-weight','1.2');await submit('member-form');await sleep(300);closeModal();nm=state.members.find((p:any)=>p.name==='Bà nội (thử)');expect(nm&&nm.weight===1.2,aT('Thành viên mới chưa được lưu.','The new member was not saved.'))});
  await part(aT('Bữa chưa nấu ghi “chưa báo” và vẫn tính suất (nấu đủ)','Uncooked meals: “not answered”, still counted'),async()=>{expect(mealOf(d,'dinner').attendance[nm.id]==='pending',aT(`Bữa tối ghi “${mealOf(d,'dinner').attendance[nm.id]}” thay vì “chưa báo”.`,`Dinner shows “${mealOf(d,'dinner').attendance[nm.id]}”.`));
   const s1=mealServings(mealOf(d,'dinner'),state),n1=need(id,d,d),want=n0+(dayQty(d,id)-q0);expect(near(s1,s0+1.2,0.01),aT(`Suất ăn ${s1}, cần ${s0+1.2}.`,`Portions ${s1}, expected ${s0+1.2}.`));expect(dayQty(d,id)>q0&&near(n1,want,1),aT(`${ing(id)?.[0]}: ${Math.round(n0)} → ${Math.round(n1)}, cần ${Math.round(want)}.`,`${id}: ${n0} → ${n1}, expected ${want}.`))});
  await part(aT('Bà báo ăn ở nhà → giữ nguyên','She eats at home → unchanged'),async()=>{await everyoneHome(d,'dinner');expect(near(mealServings(mealOf(d,'dinner'),state),s0+1.2,0.01),aT('Báo ăn ở nhà mà suất ăn đổi.','Portions changed.'))});
  await part(aT('Bà báo vắng → suất & đi chợ giảm 1,2 suất','She is away → 1.2 portions and their amounts off'),async()=>{await pick(`#main select[data-change="attendance"][data-id="${nm.id}"]`,'away');await sleep(250);expect(near(mealServings(mealOf(d,'dinner'),state),s0,0.01),aT('Báo vắng mà suất bữa tối không giảm.','Dinner portions did not drop.'));const want=n0+(dayQty(d,id)-q0);expect(near(need(id,d,d),want,1),aT(`Đi chợ ${ing(id)?.[0]}: ${Math.round(need(id,d,d))}, cần ${Math.round(want)}.`,`Shopping ${need(id,d,d)}, expected ${want}.`))})});
})();
